fn help_requested(args: &[String]) -> bool {
    args.iter().any(|arg| arg == "--help" || arg == "-h")
}

"init" => {
    rest.remove(0);
    if help_requested(&rest) {
        println!("{}", INIT_HELP);
        exit(0);
    }
    exit(init::run(&rest, cli_root.as_deref()));
}
